def seed_departments(apps, schema_editor):
    Department = apps.get_model('accounts', 'Department')
    for code, name in DEPARTMENTS:
        Department.objects.get_or_create(name=name, defaults={'code': code})


def move_student_departments(apps, schema_editor):
    Department = apps.get_model('accounts', 'Department')
    Student = apps.get_model('accounts', 'Student')
    known = {row.name: row for row in Department.objects.all()}
    legacy_number = 0
    for student in Student.objects.exclude(department_legacy=''):
        name = student.department_legacy.strip()
        if not name:
            continue
        department = known.get(name)
        if department is None:
            legacy_number += 1
            department = Department.objects.create(
                code=f'LEGACY-{legacy_number}', name=name, is_active=False)
            known[name] = department
        student.department = department
        student.save(update_fields=['department'])


def restore_student_department_names(apps, schema_editor):
    Student = apps.get_model('accounts', 'Student')
    for student in Student.objects.select_related('department'):
        student.department_legacy = (
            student.department.name if student.department_id else '')
        student.save(update_fields=['department_legacy'])


